/// 保活是否到点(纯判定,便于单测):从没发过,或距上次已满 [`WHEEL_KEEPALIVE`]。
fn keepalive_due(last: Option<Instant>, now: Instant) -> bool {
    last.is_none_or(|t| now.saturating_duration_since(t) >= WHEEL_KEEPALIVE)
}

