#[test]
fn aim_deadzone_and_unbounded_target() {
    let m = Mapper::new(crate::keymap::CoordUnit::Rel, (100, 100));
    let mut aim = Aim {
        anchor_x: 0.5,
        anchor_y: 0.5,
        drag_deadzone: 10.0,
        boundary: false,
        recenter: RecenterMode::Idle,
        ..Aim::default()
    };
    let mut st = AimState::default();
    st.ox = 8.0;
    assert_eq!(aim_effective_offset(&aim, &st), (0.0, 0.0));
    st.ox = 30.0;
    assert_eq!(aim_effective_offset(&aim, &st), (20.0, 0.0));
    let (x, y, edge) = aim_target(&m, &aim, &st);
    assert_eq!((x, y, edge), (70, 50, false));
    aim.boundary = true;
    let (x, y, edge) = aim_target(&m, &aim, &st);
    assert_eq!((x, y, edge), (70, 50, false));
    st.ox = 100.0;
    let (x, _, edge) = aim_target(&m, &aim, &st);
    assert!(x <= 99 && edge, "有边界时必须钳在屏幕内");
}

/// 无边界跑步机的几何锁(本次修复的核心):
/// ①可用矩形永远不越出屏幕 —— 锚点再贴边,注入落点也在屏内
///   (出屏触摸会被设备端整条丢弃,那正是"上下到某个临界点就不动了"的成因);
/// ②各段之和恰好等于期望偏移 —— 不再像旧实现那样把超出回转半径的部分
///   注入两遍(那正是"视角跳变"的成因);
/// ③每一段都落在可用矩形内,且下一帧的起点也在矩形内。
#[test]
fn unbounded_treadmill_band_is_on_screen_and_delivers_exact_total() {
    let m = mapper();
    let aim = Aim {
        boundary: false,
        recenter_threshold: 4000,
        ..aim_at(0.5, 0.5)
    };
    for &(ax, ay) in &[
        (500, 500),
        (0, 0),
        (999, 999),
        (7, 993),
        (999, 500),
        (500, 999),
    ] {
        let (l, r, u, d) = aim_band_limits(&m, &aim, ax, ay);
        assert!(l >= 0.0 && r >= 0.0 && u >= 0.0 && d >= 0.0);
        assert!(
            (ax as f32 - l) >= 0.0 && (ax as f32 + r) <= 999.0,
            "x 落点越出屏幕:锚点 {ax},范围 [{}, {}]",
            ax as f32 - l,
            ax as f32 + r
        );
        assert!(
            (ay as f32 - u) >= 0.0 && (ay as f32 + d) <= 999.0,
            "y 落点越出屏幕:锚点 {ay},范围 [{}, {}]",
            ay as f32 - u,
            ay as f32 + d
        );
    }

    let lim = (100.0, 120.0, 90.0, 80.0);
    // 帧内实际的偏移量最多是"可用矩形 + 一帧鼠标位移"(每帧都会被钳回矩形),
    // 所以这些都在 32 段兜底以内,必须精确送达。
    for &(ox, oy) in &[
        (250.0, -430.0),
        (-50.0, 30.0),
        (0.0, 0.0),
        (1000.0, 1000.0),
        (-3000.0, 1234.0),
    ] {
        let (segs, next) = plan_aim_treadmill(ox, oy, lim, AIM_TREADMILL_MAX_HOPS);
        // 零进展不造段(见 [`plan_aim_treadmill`] 的"零进展即停"):期望偏移为 0
        // 时段表为空,含义就是"这一段什么都不用推"。有偏移时必须是实打实的段。
        if ox != 0.0 || oy != 0.0 {
            assert!(!segs.is_empty(), "有偏移就必须产出段:{segs:?}");
        }
        let sum = segs
            .iter()
            .fold((0.0f32, 0.0f32), |a, (x, y)| (a.0 + x, a.1 + y));
        assert!(
            (sum.0 - ox).abs() < 0.5 && (sum.1 - oy).abs() < 0.5,
            "拖动总量必须等于期望偏移:{sum:?} vs ({ox}, {oy})"
        );
        for (x, y) in &segs {
            assert!(
                *x <= lim.1 + 1e-3 && *x >= -lim.0 - 1e-3,
                "该段 x 越出可用矩形:{x}"
            );
            assert!(
                *y <= lim.3 + 1e-3 && *y >= -lim.2 - 1e-3,
                "该段 y 越出可用矩形:{y}"
            );
        }
        assert!(
            next.0 <= lim.1 + 0.51 && next.0 >= -lim.0 - 0.51,
            "下一帧起点 x 越出可用矩形:{:?}",
            next
        );
        assert!(
            next.1 <= lim.3 + 0.51 && next.1 >= -lim.2 - 0.51,
            "下一帧起点 y 越出可用矩形:{:?}",
            next
        );
    }

    // 病态输入(远超一帧可能出现的偏移量):32 段兜底会截断没送完的余量,
    // 但**任何一段都不许越出矩形**(宁可少转一点,也不能把触点推出屏幕)。
    let (segs, next) = plan_aim_treadmill(-9999.0, 1234.0, lim, AIM_TREADMILL_MAX_HOPS);
    assert_eq!(segs.len(), AIM_TREADMILL_MAX_HOPS);
    for (x, y) in &segs {
        assert!(
            *x <= lim.1 + 1e-3 && *x >= -lim.0 - 1e-3,
            "兜底截断时段也必须留在矩形内:{x}"
        );
        assert!(*y <= lim.3 + 1e-3 && *y >= -lim.2 - 1e-3, "y 越出矩形:{y}");
    }
    assert!(
        next.0 <= lim.1 + 0.51 && next.0 >= -lim.0 - 0.51,
        "{next:?}"
    );
}

/// 换手必须无缝:无边界模式下连续同向推,触点始终留在屏幕内,
/// 且每一段都只推"还没送出去的那部分"(不会重复注入)。
#[test]
fn unbounded_treadmill_keeps_touch_on_screen_while_turning() {
    let m = mapper();
    let aim = Aim {
        boundary: false,
        recenter_threshold: 400,
        ..aim_at(0.5, 0.95) // 锚点偏下:向下只剩不到 50px,旧实现一路向下就在这里出屏
    };
    let (ax, ay) = aim_anchor(&m, &aim);
    let (_, _, _, down_room) = aim_band_limits(&m, &aim, ax, ay);
    assert!(down_room <= 100.0, "这个锚点向下本来就只剩不到 100px");

    // 连续同向推 30 段,每段都按"期望偏移"重算落点
    let mut off_y = 0.0f32;
    for _ in 0..30 {
        off_y += 60.0;
        let lim = aim_band_limits(&m, &aim, ax, ay);
        let (segs, next) = plan_aim_treadmill(0.0, off_y, lim, AIM_TREADMILL_MAX_HOPS);
        for (_, sy) in &segs {
            let ty = (ay as f32 + sy).round() as i32;
            assert!(
                (0..=m.h as i32 - 1).contains(&ty),
                "触点跑到屏幕外了:y={ty}"
            );
        }
        off_y = next.1; // 手指停在 next,下一段从这里继续
    }
}

/// DF-2:锚点贴边(某方向可用量为 0)时,跑步机不再空转 32 段。
///
/// 旧实现在这种情况下每一段都产出 `(0, 0)`,调用方于是为每一段发一对
/// UP/DOWN —— 单次鼠标位移最多 31 对,既灌满写队列,又把推不动的累计位移
/// 静默丢掉。现在零进展直接返回空段表,注入层一条触摸消息都不发。
#[test]
fn unbounded_treadmill_does_not_spin_on_a_zero_room_direction() {
    use crate::control::{ACTION_DOWN, ACTION_MOVE, ControlCmd};
    let m = mapper();
    // 锚点贴在左上角:向左、向上两个方向可用量都是 0
    let aim = Aim {
        boundary: false,
        recenter_threshold: 400,
        ..aim_at(0.0, 0.0)
    };
    let (ax, ay) = aim_anchor(&m, &aim);
    let lim = aim_band_limits(&m, &aim, ax, ay);
    assert_eq!((lim.0, lim.2), (0.0, 0.0), "贴边方向可用量必须为 0:{lim:?}");

    assert_eq!((lim.0, lim.2), (0.0, 0.0), "贴边方向可用量必须为 0:{lim:?}");

    // 几何:推不动的方向 ⇒ 空段表,且累计偏移仍被钳回可用矩形(不积压)
    let (segs, next) = plan_aim_treadmill(-50.0, 0.0, lim, AIM_TREADMILL_MAX_HOPS);
    assert!(segs.is_empty(), "零进展方向不该产出任何段:{segs:?}");
    assert_eq!(next, (0.0, 0.0), "推不动的位移不积压到下一帧");

    // 命令级:一条触摸消息都不发(旧实现是 1 个 DOWN + 31 对 UP/DOWN)
    let ctl = ControlClient::for_test(1000, 1000);
    let mut st = AimState::default();
    st.ox = -50.0;
    st.oy = 0.0;
    st.dead_paid = true; // 死区已扣过:直接看这一段
    aim_flush_unbounded(&ctl, &m, &aim, &mut st);
    let cmds = ctl.take_cmds();
    assert!(cmds.is_empty(), "零可用方向时不许发任何触摸消息:{cmds:?}");
    assert!(!st.down, "更不该在锚点上按下一根手指");
    assert_eq!((st.ox, st.oy), (0.0, 0.0), "推不动的位移不积压");

    // 回归:正常的可用方向照旧 —— 段表精确送达,命令是 DOWN + MOVE
    let good = (100.0, 120.0, 90.0, 80.0);
    let (segs, _) = plan_aim_treadmill(250.0, -430.0, good, AIM_TREADMILL_MAX_HOPS);
    let sum = segs
        .iter()
        .fold((0.0f32, 0.0f32), |a, (x, y)| (a.0 + x, a.1 + y));
    assert!(
        (sum.0 - 250.0).abs() < 0.5 && (sum.1 + 430.0).abs() < 0.5,
        "有可用方向时总量必须精确:{sum:?}"
    );
    let ctl = ControlClient::for_test(1000, 1000);
    let mut st = AimState::default();
    st.ox = 50.0;
    st.oy = 0.0;
    st.dead_paid = true;
    aim_flush_unbounded(&ctl, &m, &aim, &mut st);
    let actions: Vec<u8> = ctl
        .take_cmds()
        .into_iter()
        .filter_map(|c| match c {
            ControlCmd::Touch { action, .. } => Some(action),
            _ => None,
        })
        .collect();
    assert_eq!(
        actions,
        vec![ACTION_DOWN, ACTION_MOVE],
        "一段 = 按下 + 移到落点"
    );
    assert!(st.down, "正常方向照旧落指");
}

/// 拖动总量 = 落指期间所有 Move 的位移之和(抬指/重按本身不产生转动,
/// 所以换手不计入)。这就是设备端实际收到的"视角转动量"。
///
/// 命令是**分批** `take_cmds` 取走的,所以"上一笔落点"这个游标必须跨批次保留 ——
/// 否则每一批的第一条 MOVE 都没有配对的 DOWN,位移会被整段漏掉。
#[derive(Default)]
struct Rotation {
    last: Option<(i32, i32)>,
    total: f32,
}

impl Rotation {
    /// 喂入一批命令,返回这一批新增的转动量
    fn feed(&mut self, cmds: &[crate::control::ControlCmd]) -> f32 {
        use crate::control::{ACTION_DOWN, ACTION_MOVE, ACTION_UP, ControlCmd};
        let before = self.total;
        for c in cmds {
            if let ControlCmd::Touch { action, x, y, .. } = c {
                let (x, y) = (*x as i32, *y as i32);
                match *action {
                    ACTION_DOWN => self.last = Some((x, y)),
                    ACTION_MOVE => {
                        if let Some((px, py)) = self.last {
                            self.total +=
                                (((x - px) as f32).powi(2) + ((y - py) as f32).powi(2)).sqrt();
                        }
                        self.last = Some((x, y));
                    }
                    ACTION_UP => self.last = None,
                    _ => {}
                }
            }
        }
        self.total - before
    }
}

/// 用户 2026-10-11(问题 1):无边界跑步机必须**跨帧摊开**交付。
///
/// 旧实现把一次累计偏移(可达一个回转半径,用户是 200px)在同一帧里全部注入,
/// 游戏端只要对"每帧位移/速度"有任何增益或钳制,就会被放大成一次突兀的加速。
/// 新口径:单次调用最多交付 [`AIM_MAX_STEP_PX`],余量留在 `st.ox/oy`,由下一次
/// 调用接着推 —— **跨调用累计之和仍然精确等于期望偏移**(§4.14 任务2 的承诺
/// 由"单次调用内段之和"重述为"跨调用累计之和",语义不弱化)。
#[test]
fn unbounded_treadmill_spreads_a_huge_step_across_frames() {
    use crate::control::ControlCmd;
    let m = mapper();
    let aim = Aim {
        boundary: false,
        recenter_threshold: 200,
        ..aim_at(0.5, 0.5)
    };
    let (ax, ay) = aim_anchor(&m, &aim);
    let lim = aim_band_limits(&m, &aim, ax, ay);
    assert!(lim.1 > 100.0, "这个锚点向右应有充足空间:{lim:?}");

    let ctl = ControlClient::for_test(1000, 1000);
    let mut st = AimState::default();
    st.anchor_used = (ax, ay);
    st.dead_paid = true;
    // 一次"巨量"累计偏移:相当于一帧里夹带了 3000px(卡顿后的合并位移 / 甩枪)
    let want = 3000.0f32;
    st.ox = want;

    // 第一次调用:交付量必须被上限压住,余量留在累计偏移里
    let mut rot = Rotation::default();
    aim_flush_unbounded(&ctl, &m, &aim, &mut st);
    let first = rot.feed(&ctl.take_cmds());
    assert!(first > 0.0, "有余量就必须真的推出去");
    assert!(
        first <= AIM_MAX_STEP_PX + 1.5,
        "单次交付必须受上限约束(实际 {first},上限 {AIM_MAX_STEP_PX})"
    );
    let finger = st.cur.0 as f32 - ax as f32;
    assert!(
        st.ox - finger > 0.0,
        "余量必须留在累计偏移里(累计 {}/手指 {finger})",
        st.ox
    );

    // 继续推:每轮都受上限约束,直到余量送完
    let mut rounds = 1;
    while st.ox - (st.cur.0 as f32 - ax as f32) >= 0.5 && rounds < 2000 {
        aim_flush_unbounded(&ctl, &m, &aim, &mut st);
        let d = rot.feed(&ctl.take_cmds());
        assert!(
            d <= AIM_MAX_STEP_PX + 1.5,
            "第 {rounds} 轮超上限:{d}(上限 {AIM_MAX_STEP_PX})"
        );
        rounds += 1;
    }
    assert!(rounds < 2000, "余量必须在有限轮内送完");
    assert!(
        (rot.total - want).abs() < 3.0,
        "跨帧累计总量必须精确等于期望偏移:{} vs {want}",
        rot.total
    );

    // 余量为 0:一条命令都不许再发(也不许再落指/抬指)
    let sent = st.sent;
    aim_flush_unbounded(&ctl, &m, &aim, &mut st);
    let cmds: Vec<ControlCmd> = ctl.take_cmds();
    assert!(cmds.is_empty(), "没有余量时不得再注入:{cmds:?}");
    assert_eq!(st.sent, sent, "没有余量时不许再发触摸消息");
}

/// 余量推进的闭环([`aim_drain_pending`]):没有新的鼠标位移时,
/// 也要把上一轮没送完的余量推出去 —— 但**只在拖动进行中**、
/// 且**不刷新 `last_motion`**(否则静止归中会被无限推迟)。
#[test]
fn drain_pending_pushes_the_leftover_without_touching_last_motion() {
    let m = mapper();
    let aim = Aim {
        boundary: false,
        recenter_threshold: 200,
        ..aim_at(0.5, 0.5)
    };
    let (ax, ay) = aim_anchor(&m, &aim);
    let ctl = ControlClient::for_test(1000, 1000);
    let mut st = AimState::default();
    st.mode_active = true;
    st.anchor_used = (ax, ay);
    st.dead_paid = true;
    st.ox = 500.0;
    st.oy = 0.0;
    st.down = true;
    st.cur = (ax, ay);
    let motion = Instant::now() - Duration::from_millis(500);
    st.last_motion = Some(motion);

    // 手指此刻就在锚点上(手动接上的状态):游标从锚点起步
    let mut rot = Rotation {
        last: Some((ax, ay)),
        total: 0.0,
    };
    aim_drain_pending(&ctl, &m, &aim, &mut st);
    let pushed = rot.feed(&ctl.take_cmds());
    assert!(pushed > 0.0, "有落指 + 有余量时必须继续推");
    assert!(pushed <= AIM_MAX_STEP_PX + 1.5, "单轮仍然受上限约束");
    assert_eq!(st.last_motion, Some(motion), "余量推进不得刷新 last_motion");

    // 余量送完后:静止不动,一条消息都不发
    while (st.ox - (st.cur.0 as f32 - ax as f32)).abs() >= 0.5 {
        aim_drain_pending(&ctl, &m, &aim, &mut st);
        let _ = rot.feed(&ctl.take_cmds());
    }
    assert!(rot.total > 400.0, "余量必须真的被推完:{}", rot.total);
    aim_drain_pending(&ctl, &m, &aim, &mut st);
    assert!(ctl.take_cmds().is_empty(), "余量送完后必须彻底安静");

    // 没有落指(抬指状态)时什么都不做
    st.down = false;
    st.ox = 400.0;
    aim_drain_pending(&ctl, &m, &aim, &mut st);
    assert!(ctl.take_cmds().is_empty(), "没落指时不得注入");
}

#[test]
fn macro_steps_are_serializable_and_change_bind_signature() {
    use crate::keymap::{MacroAction, MacroStep};
    let action = Action::Macro(MacroAction {
        instructions: Vec::new(),
        virtual_profile: None,
        steps: vec![
            MacroStep {
                code: 30,
                pressed: true,
                delay_ms: 0,
            },
            MacroStep {
                code: 30,
                pressed: false,
                delay_ms: 40,
            },
        ],

        repeat_while_held: false,
    });
    let bind = KeyBind {
        key: 29,
        action: action.clone(),
        fps_only: false,
        tail_delay_ms: 0,
    };
    assert_ne!(binds_signature(&[bind.clone()]), binds_signature(&[]));
    let text = serde_norway::to_string(&action).unwrap();
    let back: Action = serde_norway::from_str(&text).unwrap();
    assert_eq!(back, action);
}
/// 回归(用户实测):"按下 F8 却没反应 / 状态跟自己以为的不一样,
/// 必须再关一次开一次才恢复"。
///
/// 根因是 Windows 的按键自动重复会被低级钩子报成一串 KeyPress,
/// 而旧代码对每个事件都翻转一次映射开关 —— 长按 F8 半秒就翻十几次。
/// 判定必须只认"上升沿"(刚按下的那一次)。
#[test]
fn rising_edge_ignores_key_auto_repeat() {
    // 首次按下 -> 上升沿,翻一次
    assert!(rising_edge(true, false));
    // 自动重复(键仍按着)-> 不是上升沿,绝不能再翻
    assert!(!rising_edge(true, true));
    assert!(!rising_edge(true, true));
    // 松开
    assert!(!rising_edge(false, true));
    // 再按下 -> 又是上升沿
    assert!(rising_edge(true, false));
}

