    st: &mut AimState,
    held: &Held,
    at: Instant,
) {
    let r = &aim.recoil;
    let active = r.armed() && key_set_down(&r.trigger_key, held) && aim_active(aim, st);
    st.recoil_active = active;
    if !active {
        st.recoil_last = None;
        st.recoil_frac = 0.0;
        return;
    }
    // 档位收敛:界面删档/换配置后,运行下标可能越界
    if !r.strengths.is_empty() {
        st.recoil_index = st.recoil_index.min(r.strengths.len() - 1);
    }
    let dt = st
        .recoil_last
        .map(|t| at.duration_since(t).as_secs_f32())
        .unwrap_or(0.0);
    st.recoil_last = Some(at);
    let (frac, steps) = recoil_step_plan(r.rate_hz, st.recoil_frac, dt);
    st.recoil_frac = frac;
    let strength = r.strength_at(st.recoil_index);
    if steps < 1.0 || strength <= 0.0 {
        return;
    }
    // K2er 原文:"控制视角向下移动"。触摸坐标 y 向下为正,直接加在累计偏移上。
    st.oy += strength * steps;
    let shake = r.shake_px.max(0.0);
    if shake > 0.0 {
        let mut jitter = 0.0;
        for _ in 0..(steps as usize) {
            jitter += recoil_shake(&mut st.recoil_rng);
        }
        st.ox += jitter * shake;
    }
    if aim.open_world {
        // 开放世界:落点与"水平回转"的几何由 [`open_world_on_motion`] 维护
        // (它钳的是 `open_world_radius`,不认可无边界跑步机的可用矩形),
        // 压枪就只能把偏移交给**同一条路**落下去,否则两条路各写一遍
        // `st.ox/oy` 会互相打架。
        //
        // 旧实现在生效条件里写着 `&& !aim.open_world`,等于"开放世界方案里
        // 压枪永远不生效"(用户 2026-10-11 核对的「三角洲」方案正是
        // `open_world=true` + `recoil.enabled=true`):勾了开启、绑了左键,
        // 却一点补偿都没有。现在按同一套几何注入(纵向由
        // `open_world_on_motion` 钳在锚点到上下边缘之间,不会把触点推出屏)。
        open_world_on_motion(ctl, m, aim, st, 0.0, 0.0, at, 0);
    } else {
        // 无边界走跑步机、有边界走落点钳制 —— 与鼠标位移完全同一条路。
        aim_flush(ctl, m, aim, st, at);
    }
}

pub struct Shared {
    pub profile: Profile,
    pub enabled: bool,
    pub control: Option<ControlClient>,
    /// 瞄准运行状态(界面诊断显示)
    pub aim_live: AimLive,
    /// 引擎运行状态(触点占用 / 因触点池满被拒的按下次数),界面诊断显示。
    /// 用户抱怨过"普通按键按下无反应,原因不明" —— 有了它,界面就能直接
    /// 说出"此刻占了几个触点、刚才哪个键因为挤不进去被放弃了"。
    pub live: EngineLive,

    wheels: &mut Vec<WheelState>,
    active_android_keys: &mut HashSet<u16>,
    fps_active_android_keys: &mut HashSet<u16>,
    combo_active_android_keys: &mut HashSet<u16>,
    aim: &mut AimState,
    gates: &mut PressGates,
) -> bool {
    let mut g = lock_shared(&shared);
    if target >= g.schemes.len() || target == g.active_scheme {
        return false;
    }
    // 界面上的最新改动可能还只在 `profile` 里(界面帧末才收回组合表),
    // 换车前先存一次档,免得这一帧刚改的东西随换车一起丢掉。
    g.stash_active();

    // ---- ① 抬起旧组合留下的一切 ----
    // 把控制通道临时取出拿到所有权:既能读出屏幕尺寸,又能同时可变借用 `g`
    // (与总开关键、顶栏按钮两条路径完全一致)。
    let ctl = g.control.take();
    let screen = ctl
        .as_ref()
        .map(|c| (c.screen_w, c.screen_h))
        .unwrap_or((0, 0));
    release_all(
        ctl.as_ref(),
        &mut g,
        screen,
        EngineState {
            fingers: &mut *fingers,
            fps_fingers: &mut *fps_fingers,
            combo_fingers: &mut *combo_fingers,
            wheels: &mut *wheels,
            active_android_keys: &mut *active_android_keys,
            fps_active_android_keys: &mut *fps_active_android_keys,
            combo_active_android_keys: &mut *combo_active_android_keys,
            release_fps: true,
            aim: &mut *aim,
            gates: &mut *gates,
        },
    );
    g.control = ctl;

    // ---- ①b 组合门控与旧排程 ----
    // 门控可能还记着旧车里"某一组按着/在吞键"的状态 —— 那些索引在换车后
    // 指向别的组合,甚至不存在,必须先清掉(清 active 时门控会把抬起事件
    // 补进队,幂等;真正的触碰抬起已由上面 release_all 用旧表发过)。
    combo_gate.reset();
    // 旧组合已排程的点按/滑动作废:换车后同一个索引可能换成别的动作,
    // 旧排程会落到新组合的触点上(与关映射、通道断开两条收尾路径一致)。
    cancel_combo_scheduled(scheduled);

    // ---- ② 换车 ----
    let Some(next) = g.schemes.get(target).cloned() else {
        return false;
    };
    g.profile = next;
    g.active_scheme = target;
    aim.mode_active = false;
    aim.suspended = false;
    let name = g.profile.name.clone();
    notify(&mut g.notices, format!("已切换到按键组合「{name}」"));

    // ---- ③ 按物理按键状态重建 ----
    if let Some(ctl) = g.control.as_ref() {
        if ctl.is_connected() {
            let m = g.profile.mapper((ctl.screen_w, ctl.screen_h));
            *binds_sig = binds_signature(&g.profile.binds);
            *wheel_sig = wheel_signature(&g.profile.wheels);
            *combos_sig = combos_signature(&g.profile.combos);
            // 宏触点也占池:换组合不取消宏,宏按着的手指得算进来
            let extra =
                macro_extra + usize::from(aim.down) + fps_fingers.count + combo_fingers.count;
            reconcile_binds(
                ctl,
                &m,
                &g.profile,
                wheels,
                false,
                extra,
                held,
                fingers,
                active_android_keys,
                live,
            );
            reconcile_wheels(
                ctl,
                &m,
                &g.profile,
                wheels,
                held,
                macro_extra
                    + fingers.count
                    + fps_fingers.count
                    + combo_fingers.count
                    + usize::from(aim.down),
                live,
            );
        }
    }
    true
}

