/// 而发真 ACTION_UP。两个 pid 不同,所以新指的 DOWN 一定是"新槽位",不会
/// 拿一根已按下的手指重发 DOWN。
fn aim_overlap_handoff(
    ctl: &ControlClient,
    st: &mut AimState,
    aim: &Aim,
    others: usize,
    why: &'static str,
    anchor: (i32, i32),
    from: (i32, i32),
) {
    let old_pid = st.active_pid();
    st.pid_alt = !st.pid_alt;
    ctl.touch_down(st.active_pid(), anchor.0, anchor.1);
    ctl.touch_up(old_pid, from.0, from.1);
    st.sent += 2;
    st.cur = anchor;
    st.handoffs += 1;
    log_handoff(st, aim, others, why, old_pid);
}
```

