/// (例如临时轮盘仍被当成"已启用",或按住记录还留着)。
pub(crate) fn release_all(
    ctl: Option<&ControlClient>,
    shared: &mut Shared,
    screen: (u32, u32),
    st: EngineState<'_>,
) {
    match ctl {
        Some(c) => {
            let m = shared.profile.mapper(screen);
            // 瞄准触点一并抬起(否则松手后仍按在屏幕上)
            if st.release_fps {
                aim_lift(c, st.aim);
            }
            // 遍历按下表本身的长度而不是当前绑定数:被删掉的槽位里可能还记着"按着",
            // 漏掉它就是一个永久卡在设备上的触点(触点池会被越用越少)。
            let n = st.fingers.down.len().max(shared.profile.binds.len());
            for idx in 0..n {
                if st.fingers.release(idx) {
                    let (x, y) = bind_point(&shared.profile, &m, idx);
                    c.touch_up(bind_pid(idx), x, y);
                                            c.key(true, keycode);
                                        }
                                    } else if macro_active_android_keys.remove(&keycode) {
                                        c.key(false, keycode);
                                    }
                                }
                                SchedAct::MacroFps { on } => {
                                    aim.mode_active = on;
                                    aim.suspended = false;
                                    if !on {
                                        aim_lift(c, &mut aim);
                                        release_fps_binds(
                                            c,
                                            &g.profile.mapper((c.screen_w, c.screen_h)),
                                            &g.profile.binds,
                                            &mut fps_fingers,
                                            &mut fps_active_android_keys,
                                        );
                                    }
                                }
                                SchedAct::MacroWheel { wheel, part, down } => {
                            fresh_press,
                            &ev,
                            &mut fps_fingers,
                            &mut fps_active_android_keys,
                            &mut scheduled,
                            reserved,
                            &mut live,
                            &mut gates,
                        ) {
                            pending_notice = Some(format!("FPS 键位: {}", reason.hint(k)));
                        }
                    }
                } else {
                    aim_lift(ctl, &mut aim);
                    release_fps_binds(
                        ctl,
                        &m,
                        &g.profile.binds,
                        &mut fps_fingers,
                        &mut fps_active_android_keys,
                    );

