    fn touch_cmds(ctl: &ControlClient) -> Vec<(u8, u64, i32, i32)> { ... }

    /// 瞄准触点流的审计结果。
    #[derive(Default, Debug)]
    struct AimAudit {
        /// 换手次数:`DOWN(新 pid)` 紧跟 `UP(旧 pid)`、两个 pid 不同的窗口数
        handoffs: usize,
        /// 拖动过程中是否出现过"零瞄准触点"的瞬间(结尾那次抬指不算)
        zero_gap: bool,
        /// 是否抬过一根从没按下的 pid(计数减到负数)
        illegal_up: bool,
        down: usize,
        up: usize,
    }

    fn audit_aim_touches(cmds: &[(u8, u64, i32, i32)]) -> AimAudit {
        use crate::control::{ACTION_DOWN, ACTION_UP};
        let mut out = AimAudit::default();
        let aim: Vec<&(u8,u64,i32,i32)> = cmds.iter().filter(|c| is_aim_pid(c.1)).collect();
        let mut live: i64 = 0;
        for (i, c) in aim.iter().enumerate() {
            match c.0 {
                ACTION_DOWN => { live += 1; out.down += 1; }
                ACTION_UP => { live -= 1; out.up += 1; if live < 0 { out.illegal_up = true; } }
                _ => {}
            }
            if live == 0 && i + 1 < aim.len() { out.zero_gap = true; }
        }
        for w in cmds.windows(2) {
            if is_aim_pid(w[0].1) && is_aim_pid(w[1].1) && w[0].0 == ACTION_DOWN && w[1].0 == ACTION_UP && w[0].1 != w[1].1 {
                out.handoffs += 1;
            }
        }
        out
    }
