        // 换手次数 ≤ 总量 / band + 1(旧形态的段表与现在完全相同,
        // 重叠只是把"UP→DOWN"换成"DOWN→UP",不产生额外的换手)。
        let upper = (want / band as f32) as u64 + 1;
