            // 不会因为瞄准而收到真 `ACTION_UP`。
            aim_overlap_handoff(ctl, st, band, "无边界跑步机", (ax, ay), (tx, ty));
        }
    }
    // 手指现在停在"相对锚点的 next"处;写回累计偏移,下一帧从这里继续累计。
